<?php $items = kimpu_homepage_page_children( 'kimpu_team_source_page', 0 ); ?><section class="section <?php echo esc_attr( kimpu_homepage_section_classes( 'team' ) ); ?>" id="team"><div class="container"><?php kimpu_homepage_section_header( 'team' ); ?><?php if ( $items ) : ?><div class="homepage-card-grid homepage-columns-<?php echo esc_attr( 'four' === kimpu_homepage_section_value( 'team', 'layout', 'three' ) ? '4' : '3' ); ?>"><?php foreach ( $items as $item ) : ?><article class="team-card"><?php if ( has_post_thumbnail( $item->ID ) ) { echo get_the_post_thumbnail( $item->ID, 'medium', array( 'alt' => esc_attr( get_the_title( $item->ID ) ) ) ); } ?><div class="content-card-body"><h3><?php echo esc_html( $item->post_title ); ?></h3><p><?php echo esc_html( wp_trim_words( wp_strip_all_tags( $item->post_content ), 24 ) ); ?></p><a class="text-link" href="<?php echo esc_url( get_permalink( $item->ID ) ); ?>"><?php esc_html_e( 'View profile', 'kimpu-multipurpose' ); ?> →</a></div></article><?php endforeach; ?></div><?php else : ?><p class="empty-state"><?php esc_html_e( 'Select a parent page with published child pages to show team members.', 'kimpu-multipurpose' ); ?></p><?php endif; ?></div></section>
